INSERT INTO about_content (id, intro_headline, intro_summary, vision_text, mission_text, team_photo_url, team_photo_caption) VALUES (1, 'THE LEGACY OF UNTAMED ENDURANCE', 'Team Red Baron is Pimpri Chinchwad College of Engineering’s official collegiate offroad racing team. We design, manufacture, test, and race high-performance All-Terrain Vehicles (ATVs) for national BAJA SAE India competitions.', 'To become a leading student motorsports team recognized for innovation, technical excellence, and teamwork in designing and developing high-performance electric All-Terrain Vehicles, while representing the institution successfully at national and international competitions such as eBAJA SAE India and Baja SAE International.', 'To design and manufacture reliable, competitive electric ATVs through innovative engineering, while developing technical, leadership, and teamwork skills through hands-on learning, representing our institution with excellence, and advancing sustainable automotive technologies.', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/team/IMG_9368.jpg', 'Team Red Baron Squad') ON CONFLICT (id) DO UPDATE SET intro_headline = EXCLUDED.intro_headline;
