INSERT INTO featured_partners (name, tier_label, logo_url, background_image_url, description, contribution, website_url, sort_order) VALUES ('VARROC ENGINEERING', 'TITLE PARTNER', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/sponsors/TITLE/VARROC.png', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/hero/IMG_4588.png', 'Varroc has been instrumental in backing Team Red Baron''s structural and powertrain development. Through their Tier-1 automotive manufacturing resources, TRB engineers gain access to advanced metallurgy, component heat-treatment, and automotive lighting technology.', 'Chassis Components, Powertrain Support & Technical Mentorship', 'https://varroc.com', 0);
INSERT INTO featured_partners (name, tier_label, logo_url, background_image_url, description, contribution, website_url, sort_order) VALUES ('ALTIUM LLC', 'TITLE ELECTRONICS PARTNER', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/sponsors/TITLE/ALTIUM.png', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/images_timeline/2023.png', 'Altium empowers our Electronics & Telemetry sub-team with full enterprise PCB design licenses. Using Altium Designer, TRB student engineers synthesize custom telemetry sender boards, wheel-speed sensor nodes, and live pitwall telemetry feeds.', 'Altium Designer PCB EDA Suite & Cloud Collaboration', 'https://www.altium.com', 1);
INSERT INTO featured_partners (name, tier_label, logo_url, background_image_url, description, contribution, website_url, sort_order) VALUES ('SKF GROUP', 'PLATINUM ROTATIONAL PARTNER', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/sponsors/PLATINUM/SKF.png', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/images_timeline/2022.avif', 'SKF provides TRB with ultra-low friction ceramic hybrid and deep-groove ball bearings for our custom 4WD transfer case and wheel hubs, reducing parasitic drivetrain power loss by over 8%.', 'High-Precision Drivetrain & Wheel Hub Bearings', 'https://www.skf.com', 2);
INSERT INTO featured_partners (name, tier_label, logo_url, background_image_url, description, contribution, website_url, sort_order) VALUES ('FLUKE CORPORATION', 'PLATINUM MEASUREMENT PARTNER', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/sponsors/PLATINUM/FLUKE.png', 'https://axzwucvnrjtenvvrxfew.supabase.co/storage/v1/object/public/trb-media/images_timeline/2025.jpg', 'Fluke equips Team Red Baron with thermal imaging cameras and precision digital multimeters to diagnose engine heat dissipation, CVT belt thermals, and battery pack telemetry during 4-hour endurance runs.', 'Thermal Imaging & Diagnostic Metrology Hardware', 'https://www.fluke.com', 3);
